sys_variable_value.value:
(function(outputs, steps, params, stepResult, assertEqual) {
    var testAccounts = [
        { Id: '001dN000011ZtlJQAS', Name: 'Apollo Hospitals Hyderabad', Phone: '040-23607777', Website: 'www.apollohospital.com', Type: 'Prospect', Industry: 'Healthcare', Description: 'Apollo Hospitals Hyderabad is procuring ICU monitoring equipment', ParentId: '001dN000011aHm4QAE', OwnerId: '005dN00000ASYH7QAP' },
        { Id: '001dN000011Z2nRQAS', Name: 'testing1', Phone: '', Website: '', Type: 'Competitor', Industry: 'Education', Description: '', ParentId: '', OwnerId: '005dN00000ASYH7QAP' }
    ];

    // Create import set for accounts
    var importSet = new GlideRecord('sys_import_set');
    importSet.initialize();
    importSet.setValue('table_name', 'x_1775706_salesfor_sf_acct_stg');
    importSet.setValue('state', 'loaded');
    var importSetId = importSet.insert();

    // Insert staging rows
    for (var i = 0; i < testAccounts.length; i++) {
        var acct = testAccounts[i];
        var row = new GlideRecord('x_1775706_salesfor_sf_acct_stg');
        row.initialize();
        row.setValue('sys_import_set', importSetId);
        row.setValue('sys_import_state', 'pending');
        row.setValue('u_id', acct.Id);
        row.setValue('u_name', acct.Name);
        row.setValue('u_phone', acct.Phone);
        row.setValue('u_website', acct.Website);
        row.setValue('u_type', acct.Type);
        row.setValue('u_industry', acct.Industry);
        row.setValue('u_description', acct.Description);
        row.setValue('u_parentid', acct.ParentId);
        row.setValue('u_ownerid', acct.OwnerId);
        row.insert();
    }

    // Run the account transform
    var isGr = new GlideRecord('sys_import_set');
    isGr.get(importSetId);
    var transformer = new GlideImportSetTransformer();
    transformer.transformAllMaps(isGr);

    // Verify Apollo Hospitals account
    var apollo = new GlideRecord('x_1775706_salesfor_sf_account');
    apollo.addQuery('x_1775706_salesf_1_salesforce_id', '001dN000011ZtlJQAS');
    apollo.query();
    assertEqual({ name: 'Apollo account created', shouldbe: true, value: apollo.hasNext() });
    if (apollo.next()) {
        assertEqual({ name: 'Account name = Apollo Hospitals Hyderabad', shouldbe: 'Apollo Hospitals Hyderabad', value: apollo.getValue('name') });
        assertEqual({ name: 'Account phone mapped', shouldbe: '040-23607777', value: apollo.getValue('phone') });
        assertEqual({ name: 'Account website mapped', shouldbe: 'www.apollohospital.com', value: apollo.getValue('website') });
        assertEqual({ name: 'Account industry lowercased', shouldbe: 'healthcare', value: apollo.getValue('industry') });
        outputs.apollo_sys_id = apollo.getUniqueValue();
    }

    // Verify testing1 account
    var test1 = new GlideRecord('x_1775706_salesfor_sf_account');
    test1.addQuery('x_1775706_salesf_1_salesforce_id', '001dN000011Z2nRQAS');
    test1.query();
    assertEqual({ name: 'testing1 account created', shouldbe: true, value: test1.hasNext() });
    if (test1.next()) {
        assertEqual({ name: 'testing1 name mapped', shouldbe: 'testing1', value: test1.getValue('name') });
    }

    outputs.acct_import_set_id = importSetId.toString();
    stepResult.setOutputMessage('Staged and transformed 2 accounts successfully');
})(outputs, steps, params, stepResult, assertEqual);

